fixtures.content:
@page {
  size: A4;
  margin: 18mm 16mm 20mm 16mm;
}

body {
  font-family: "Inter", sans-serif;
  font-size: 10.5pt;
  line-height: 1.45;
  color: #1d2229;
}

h1 {
  font-size: 28pt;
  margin: 0 0 8mm;
  page-break-before: always;
}

h2 {
  font-size: 16pt;
  margin: 10mm 0 4mm;
}

h3 {
  font-size: 12pt;
  margin: 6mm 0 2mm;
}

p {
  margin: 0 0 3mm;
}

.figure {
  margin: 6mm 0;
}

.figure img {
  width: 100%;
}
